<script setup lang="ts">import {nextTick,onMounted,reactive,ref,watch} from 'vue';import {requirementRepository} from '../../services/requirementRepository';import {productRepository} from '../../services/productRepository';import RemoteSelect from './RemoteSelect.vue';import VersionSelect from './VersionSelect.vue';const props=defineProps<{kind:'design'|'dev'|'bug';modelValue?:Record<string,unknown>|null}>();const emit=defineEmits<{save:[value:Record<string,unknown>];cancel:[]}>();const form=reactive<any>({title:'',description:'',status:'',priority:'',ownerName:'',developer:'',dueDate:'',productLineId:'',versionId:''});const employees=ref<Array<{value:string;label:string}>>([]);const productLines=ref<Array<{value:string;label:string}>>([]);const loadingOptions=ref(true);const syncing=ref(false);watch(()=>props.modelValue,(value)=>{syncing.value=true;Object.assign(form,{title:'',description:'',status:'',priority:'',ownerName:'',developer:'',dueDate:'',productLineId:'',versionId:'',...(value||{})});void nextTick(()=>{syncing.value=false;});},{immediate:true});watch(()=>form.productLineId,(next,previous)=>{if(!syncing.value&&next!==previous)form.versionId='';});onMounted(async()=>{try{const [people,lines]=await Promise.all([requirementRepository.employees(),productRepository.productLines()]);employees.value=people.map(item=>({value:String(item.name||item.id||''),label:String(item.name||item.id||'')})).filter(item=>item.value);productLines.value=lines.map(item=>({value:String(item.id||''),label:String(item.name||item.code||item.id||'')})).filter(item=>item.value);}finally{loadingOptions.value=false;}});</script>
<template><form class="work-item-form" @submit.prevent="emit('save',{...form})"><label>标题<input v-model="form.title" required placeholder="请输入标题"/></label><label>描述<textarea v-model="form.description" rows="4" placeholder="请输入描述"/></label><div class="form-grid"><RemoteSelect v-model="form.status" label="状态" :options="[{value:'待处理',label:'待处理'},{value:'进行中',label:'进行中'},{value:'已完成',label:'已完成'}]" placeholder="请选择状态"/><RemoteSelect v-model="form.priority" label="优先级" :options="[{value:'紧急',label:'紧急'},{value:'高',label:'高'},{value:'中',label:'中'},{value:'低',label:'低'}]" placeholder="请选择优先级"/></div><div class="form-grid"><RemoteSelect v-model="form.ownerName" label="负责人" :options="employees" :loading="loadingOptions" placeholder="请选择负责人"/><RemoteSelect v-if="kind==='dev'" v-model="form.developer" label="开发者" :options="employees" :loading="loadingOptions" placeholder="请选择开发者"/></div><RemoteSelect v-model="form.productLineId" label="产品线" :options="productLines" :loading="loadingOptions" placeholder="请选择产品线"/><VersionSelect v-model="form.versionId" :product-line-id="form.productLineId"/><div class="form-actions"><button type="button" class="secondary" @click="emit('cancel')">取消</button><button type="submit" class="primary">保存</button></div></form></template>
